import {windowInfo} from './advanced-games.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(action,label,value,disabled=false)=>`<button class="btn" data-action="${action}" ${value===undefined?'':`data-value="${value}"`} ${disabled?'disabled':''}>${label}</button>`;
export function advancedArt(g){
 if(g.id==='islands')return `<div class="mini-grid" aria-hidden="true">${[1,1,0,0,0,1,0,1,0,0,0,1].map(n=>`<i class="${n?'land':''}"></i>`).join('')}</div>`;
 if(g.id==='window')return '<div class="window-mini" aria-hidden="true">A <strong>B A N C</strong> D</div>';
 if(g.id==='lis')return '<div class="lis-mini" aria-hidden="true">1 <b>→</b> 2 <b>→</b> 4 <b>→</b> 5</div>';
 return '<div class="water-mini" aria-hidden="true"><i></i><span>28</span><i></i></div>';
}
export function advancedBoard(g,s){
 const r=g.rounds[s.round];let body,title,subtitle,steps;
 if(g.id==='water'){
  title=s.phase==='measure'?'Measure the current container.':'Which wall can you safely discard?';
  const h=Math.min(r.values[s.left],r.values[s.right]),width=s.right-s.left,area=h*width,scale=150/Math.max(...r.values,1),dx=480/(r.values.length-1),x=i=>30+i*dx;
  subtitle=s.done?'All useful pairs considered.':`Left index ${s.left}, right index ${s.right}. Width ${width}, limiting height ${h}.`;
  body=`<svg class="water-viz" viewBox="0 0 540 230" role="img" aria-label="Water between indices ${s.left} and ${s.right}, width ${width}, height ${h}"><line x1="18" y1="185" x2="522" y2="185" stroke="#b7c4b3"/><rect x="${x(s.left)}" y="${185-h*scale}" width="${width*dx}" height="${h*scale}" fill="#84c5d688"/>${r.values.map((v,i)=>`<line x1="${x(i)}" y1="185" x2="${x(i)}" y2="${185-v*scale}" stroke="${i===s.left||i===s.right?'#e78958':'#a8bba0'}" stroke-width="9" stroke-linecap="round"/><text x="${x(i)}" y="${172-v*scale}" text-anchor="middle">${v}</text><text x="${x(i)}" y="211" text-anchor="middle" class="axis-label">${i}${i===s.left?' · L':i===s.right?' · R':''}</text>`).join('')}</svg><div class="record-row"><div>Width<strong>${width}</strong></div><div>Lower wall<strong>${h}</strong></div><div>Best area<strong>${s.best}</strong></div></div><div class="controls">${s.done?'':s.phase==='measure'?[...new Set([Math.max(0,area-width),area,area+width])].sort((a,b)=>a-b).map(n=>button('area',`${n} units²`,n)).join(''):button('left','Move left wall →')+button('right','← Move right wall')}</div>`;
  steps=['Area = distance between pointers × shorter height.','Record the best area before moving a pointer.','Move the shorter wall. Reducing width while keeping it cannot improve the result.'];
 }else if(g.id==='lis'){
  title='Choose the best earlier chain to extend.';
  subtitle=s.done?'The largest saved length is your answer.':`Current value: ${r.values[s.index]}. Select an earlier smaller value with the largest DP count, or start a new chain.`;
  const dx=480/Math.max(1,r.values.length-1),x=i=>30+i*dx;
  body=`<svg class="lis-links" viewBox="0 0 540 90" role="img" aria-label="Arrows show saved predecessor links between array indices">${s.parents.map((j,i)=>j<0?'':`<path d="M ${x(j)} 80 Q ${(x(j)+x(i))/2} ${8+Math.abs(i-j)*3} ${x(i)} 80" fill="none" stroke="#9e8cc2" stroke-width="2"/><circle cx="${x(i)}" cy="80" r="3" fill="#79669b"/>`).join('')}</svg><div class="dp-array">${r.values.map((v,i)=>`<button data-action="extend" data-value="${i}" class="dp-cell ${i===s.index?'current':''} ${i<s.index&&v<r.values[s.index]?'eligible':''}" ${s.done||i>=s.index?'disabled':''} aria-label="Extend from index ${i}, value ${v}, saved length ${s.dp[i]??'unknown'}"><small>index ${i}</small><strong>${v}</strong><span>dp = ${s.dp[i]??'?'}</span></button>`).join('')}</div><p class="viz-caption">Green: smaller earlier values. Purple arcs: saved predecessor links. Equal values do not qualify.</p><div class="record-row"><div>Best length so far<strong>${s.dp.length?Math.max(...s.dp):0}</strong></div></div><div class="controls">${s.done?'':button('extend','Start a new chain · length 1',-1)}</div>`;
  steps=['Every value can begin a chain of length 1.','Look only to earlier, strictly smaller values. Extend the one with the largest DP count.','Save that count + 1 at this index. Return the maximum of all DP entries.'];
 }else if(g.id==='islands'){
  title='Explore one connected island at a time.';
  subtitle=s.done?'Every land cell is accounted for.':s.queue.length?'Visit the highlighted cell at the front of your queue.':'Choose any unvisited land cell to start the next island.';
  const cols=r.grid[0].length;
  body=`<div class="island-grid" style="--columns:${cols}" role="group" aria-label="Island map">${r.grid.flatMap((row,y)=>[...row].map((v,x)=>{const i=y*cols+x;return `<button class="island-cell ${v==='0'?'sea':'land'} ${s.visited.includes(i)?'visited':''} ${s.queue.includes(i)?'queued':''} ${s.queue[0]===i?'next-cell':''}" style="--island-color:${['#98b887','#b3a0d5','#e6ad86','#87b9c8','#c9bb78'][(s.labels[i]-1)%5]||'#d7e6ce'}" data-action="visit" data-value="${i}" ${s.done?'disabled':''} aria-label="Row ${y}, column ${x}: ${v==='0'?'water':s.visited.includes(i)?'visited island '+s.labels[i]:s.queue.includes(i)?'queued land':'unvisited land'}"><strong>${v==='0'?'≈':s.labels[i]||'1'}</strong><small>${y},${x}</small></button>`;})).join('')}</div><p class="viz-caption">Coordinates are (row, column), starting at (0, 0). 1 = unvisited land · ≈ = water · colored numbers identify visited islands. Diagonal cells stay separate.</p><div class="queue-box"><strong>QUEUE · FRONT FIRST</strong><div>${s.queue.length?s.queue.map((i,j)=>`<span class="${j===0?'front':''}">(${Math.floor(i/cols)}, ${i%cols})</span>`).join(' → '):'Empty — start a new island'}</div></div><div class="record-row"><div>Islands found<strong>${s.island}</strong></div><div>Land visited<strong>${s.visited.length}</strong></div></div>`;
  steps=['Each unvisited land cell starts a new connected component.','Add unvisited orthogonal neighbors to the queue. Never enqueue a cell twice.','Finish the queue before starting another island. Water and diagonal contact do not connect components.'];
 }else{
  title='Collect the target, then tighten the window.';
  const info=windowInfo(r,s);
  subtitle=s.done?'Scan complete.':info.valid?'Every required occurrence is covered. Record this window and shrink.':s.right<r.values.length?'Some required occurrences are missing. Expand to the right.':'The right edge is at the end and coverage is incomplete. Finish the scan.';
  body=`<div class="target-word">TARGET <b>${r.target}</b><span>Counts matter, including repeated letters.</span></div><div class="window-strip">${r.values.map((c,i)=>`<div class="window-cell ${i>=s.left&&i<s.right?'inside':''}"><small>${i}</small><strong>${c}</strong><span>${i===s.left?'L':''}${i===s.right?'R':''}</span></div>`).join('')}<div class="window-end">${s.right===r.values.length?'R → end':''}</div></div><p class="viz-caption">Window [L, R): includes L, excludes R. Current: <b>${info.text?esc(info.text):'empty'}</b></p><div class="letter-counts">${Object.keys(info.need).map(c=>`<div class="${(info.have[c]||0)>=info.need[c]?'covered':'missing'}"><strong>${c}</strong><span>${info.have[c]||0} / ${info.need[c]}</span><small>${(info.have[c]||0)>=info.need[c]?'covered':'missing'}</small></div>`).join('')}</div><div class="record-row"><div>Best window<strong>${s.best===null?'—':esc(s.best)}</strong></div></div><div class="controls">${s.done?'':button('expand','Expand right →')+button('shrink','Save & shrink left →')+button('finish','Finish scan')}</div>`;
  steps=['Expand right while a required character count is missing.','When valid, save the window if it is shorter, then remove its leftmost character.','Continue expanding and shrinking. Counts must cover every copy in the target.'];
 }
 const feedback=s.message?`<p class="feedback ${s.error?'error':''}">${esc(s.message)}${s.done?`<br><strong>${s.round+1===g.rounds.length?'Pattern unlocked. Opening your coding exercise…':'Loading the next round…'}</strong>`:''}</p>`:'';
 return `<div class="game-layout"><section class="game-board advanced-board"><div class="board-top"><span>ROUND ${s.round+1} OF ${g.rounds.length}</span><span class="target">${g.tag}</span></div><h2 class="instruction">${title}</h2><p class="subtext">${subtitle}</p>${body}<div id="game-feedback" aria-live="polite">${feedback}</div></section><aside class="explanation"><div class="icon">✳</div><h2>${g.concept}</h2><ol>${steps.map(text=>`<li>${text}</li>`).join('')}</ol><div class="divider">Explore each decision.<br>Wrong moves explain the invariant.</div></aside></div>`;
}
